# Справочный список

Типовые проблемы:

- дубли правил;
- противоречия между инструкциями;
- устаревшие команды;
- неясная область действия.

Список используется как стартовая сетка и не должен закрывать другие подтверждённые проблемы.

STATE_PATH = '.review/project-review-state.json'

def new_state():
    return {'schema_version': 3, 'status': 'in_progress'}

def init(repo):
    atomic_write(repo / STATE_PATH, new_state())

IMPACT_PATH = 'project-impact.json'
STATE_PATH = '.review/state.json'

def project_ontology(repo):
    return {'paths': {node['path'] for node in load_impact(repo)['nodes']}}

def init(repo):
    state_path = repo / STATE_PATH
    state = load_state(state_path) if state_path.is_file() else new_state()
    if (repo / IMPACT_PATH).is_file():
        state['ontology_scope'] = project_ontology(repo)
    atomic_write(state_path, state)

def _probe(original):
    def wrapped(self):
        result = original(self)
        if not result:
            _record(self, 'missing')
        return result
    return wrapped

Path.is_file = _probe(_original_is_file)
Path.is_dir = _probe(_original_is_dir)
